fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
    let (height, one_row) = self.fit.heights(&self.editor, window, cx);
    // Before the editor lays out this frame, so it scrolls only once its
    // text takes more than its most rows.
    self.fit.keep_cursor_in_view(&self.editor, window, cx);
    // Without copying the text, however long it is.
    let empty = self.editor.read(cx).text().len() == 0;
    // A task queues only behind one of its own lane; a question is asked
    // straight away, beside whatever the harness is working on, so it
    // never queues.
    let queues = self.busy.queues(TABS[self.selected_tab]);

    // Follows how the editor is laid out, to fit it anew.
    let track_layout =
        GrowToFit::tracker(&self.editor, cx.entity().downgrade(), |this: &mut Self| {
            &mut this.fit
        });

    // Code, the chain, Spec, Ask, and Freeform are tabs side by side, each its own
    // bar so that selecting the chain can show Code and Spec selected
    // along with it, as one locked tab. The chain shows an icon: broken
    // and dimmed until selected, then joined. Selecting it pulls in half
    // its width from either side, as though by negative margins, so Code
    // and Spec slide together until they meet beneath it and it sits on
    // the seam between them.
    let selected = self.selected_tab;
    let unified = selected == BOTH_TAB;
    let chain_width = self.chain_width.unwrap_or(CHAIN_WIDTH_ESTIMATE);
    let join = SpringAnimation::new(CHAIN_SPRING).to(if unified { 1. } else { 0. });
    let hues = Hues::of(cx);
    let tint = move |position| tint(hues, position);
    // Each tab's label is in its mode's colour at full strength, selected
    // or not.
    let label_color = move |ix: usize| Hsla {
        a: 1.,
        ..tint(ix as f32)
    };
    // In Chain's purple, selected or not: a joined chain once selected,
    // and a broken one dimmed to half opacity until then.
    let chain_color = mode_color(SendMode::Both, cx);
    let chain_icon = Icon::new(if unified {
        IconName::Link
    } else {
        IconName::Unlink
    })
    .text_color(if unified {
        chain_color
    } else {
        chain_color.opacity(0.5)
    });
    // The strip, the selected tab, and the body beneath it: flat
    // surfaces with no line anywhere, the selected tab joined to the body.
    let palette = crate::theme::palette(cx);
    let strip = crate::theme::color(palette.ribbon);
    let surface = crate::theme::color(palette.ribbon_tabs);
    let hover = crate::theme::color(palette.hover);
    let chat_input = cx.entity().downgrade();
    // A tab: its label in its mode's colour, or the chain's icon, marked
    // selected only by its background. The chain has none of its own, so
    // the joined Code and Spec show through beneath it.
    let full_tab = |ix: usize| {
        let chat_input = chat_input.clone();
        let is_selected = ix != BOTH_TAB
            && (selected == ix
                || (unified && matches!(TABS[ix], SendMode::Code | SendMode::Spec)));
        let inner = gpui_kit::TestSupportExt::test_support(h_flex().id(0usize))
            .h(TAB_STRIP_HEIGHT)
            .items_center()
            .px_2()
            .text_sm()
            .cursor_pointer()
            .when(is_selected, |tab| tab.bg(surface))
            .when(!is_selected && ix != BOTH_TAB, |tab| {
                tab.hover(move |tab| tab.bg(hover))
            })
            .map(|tab| match TABS[ix] {
                SendMode::Both => {
                    tab.px_1p5()
                        .child(chain_icon.clone().small())
                        .tooltip(|window, cx| {
                            Tooltip::new(SendMode::Both.label()).build(window, cx)
                        })
                }
