                // purple, shifting to it as they slide together beneath
                // the chain and back as they part.
                mode @ (SendMode::Code | SendMode::Spec) => {
                    let own = label_color(ix);
                    tab.child(div().child(mode.label()).with_spring(
                        ("chain-join-label", ix),
                        join.clone(),
                        move |label, joined| {
