            // The walkthrough points at each mode's tab.
            .child(crate::walkthrough::mark(crate::walkthrough::Target::ChatTab(
                TABS[ix],
            )))
            .child(inner)
    };
    let measure_chain = {
        let chat_input = chat_input.clone();
        canvas(
            |_, _, _| {},
            move |bounds, _, _, cx| {
