        div()
            .id("chat-tabs")
            .relative()
            .flex()
            .h(TAB_STRIP_HEIGHT)
            .items_center()
            .bg(strip)
            .child(code)
            .child(spec)
            .child(ask)
            .child(freeform)
            .child(attach_images)
