        .rounded(px(4.))
        .bg(crate::theme::color(palette.darkest))
        .child(input_area);
    // Lets UI tests find the box; inert in normal builds.
    let input_area = gpui_kit::TestSupportExt::test_support(input_area);

    div()
        .track_focus(&self.focus_handle)
        .flex()
        .flex_col()
        .key_context(CONTEXT)

